CREATE OR REPLACE FUNCTION public.gallery_begin_purge(target uuid, confirm_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e gallery_events;
begin
 select * into e from gallery_events where id=target for update;
 if not found then raise exception 'Event unavailable'; end if;
 if e.deleted_at is null or e.active or e.name is distinct from confirm_name then raise exception 'Trash the event and confirm its exact name'; end if;
 if e.deleted_at > now()-interval '135 minutes' then raise exception 'Recent upload links must expire before deletion'; end if;
 if (gallery_purge_inventory(target)->>'unknownExports')::bigint>0 then raise exception 'Unrecognized export paths require review'; end if;
 if exists(select 1 from gallery_requests where event_id=target and status not in ('completed','cancelled')) then raise exception 'Complete or cancel outstanding gallery requests first'; end if;
 update gallery_events set purge_started_at=coalesce(purge_started_at,now()) where id=target;
 return gallery_purge_inventory(target);
end; $function$

CREATE OR REPLACE FUNCTION public.gallery_capture_finish(p_hash text, p_request uuid, p_original_bytes integer, p_preview_bytes integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; pid uuid;
begin
 s=public.gallery_station_check(p_hash,'capture');
 select photo_id into pid from public.gallery_capture_receipts where station_id=s.id and request_id=p_request;
 if pid is null then raise exception 'Capture unavailable' using errcode='PT404'; end if;
 if p_original_bytes not between 1 and 4194304 or p_preview_bytes not between 1 and 1048576 then raise exception 'Invalid image size'; end if;
 update public.gallery_photos set ready=true,hidden=false,original_bytes=p_original_bytes,preview_bytes=p_preview_bytes where id=pid and not ready;
 insert into public.gallery_print_jobs(id,event_id) values(pid,s.event_id) on conflict(id) do nothing;
 return pid;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_capture_reserve(p_hash text, p_request uuid, p_digest text)
 RETURNS gallery_photos
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; r public.gallery_capture_receipts; p public.gallery_photos; key text;
begin
 s=public.gallery_station_check(p_hash,'capture');
 select * into r from public.gallery_capture_receipts where station_id=s.id and request_id=p_request;
 if found then
  if r.digest<>p_digest then raise exception 'Capture changed' using errcode='PT409'; end if;
  select * into p from public.gallery_photos where id=r.photo_id;
  -- Recover a capture finalized through the existing owner upload workflow.
  if p.ready then insert into public.gallery_print_jobs(id,event_id) values(p.id,s.event_id) on conflict(id) do nothing; end if;
  return p;
 end if;
 if s.submitted>=1000 or s.last_capture_at>now()-interval '3 seconds' then raise exception 'Capture limit reached' using errcode='PT429'; end if;
 p.id=gen_random_uuid(); key=s.event_id::text||'/'||p.id::text;
 insert into public.gallery_photos(id,event_id,filename,sample_asset,original_key,preview_key,position,ready,hidden)
 values(p.id,s.event_id,'Station-'||p.id::text||'.jpg',null,key||'/original.jpg',key||'/preview.jpg',extract(epoch from now())::integer,false,true) returning * into p;
 insert into public.gallery_capture_receipts values(s.id,p_request,p.id,p_digest);
 update public.gallery_stations set submitted=submitted+1,last_capture_at=now() where id=s.id;
 return p;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_experience_check(p_token text)
 RETURNS gallery_guest_sessions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_guest_sessions;
begin
 select s1.* into s from public.gallery_guest_sessions s1 join public.gallery_experiences e on e.event_id=s1.event_id join public.gallery_events ev on ev.id=e.event_id
 where s1.token_hash=p_token and s1.link_hash=e.token_hash and e.enabled and e.closes_at>now() and ev.active and ev.deleted_at is null and ev.purge_started_at is null;
 if not found then raise exception 'This event link has closed or changed' using errcode='PT403'; end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_experience_session(p_link text, p_token text, p_user uuid DEFAULT NULL::uuid)
 RETURNS gallery_guest_sessions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.gallery_experiences; s public.gallery_guest_sessions;
begin
 select * into e from public.gallery_experiences where token_hash=p_link for update;
 if not found or not e.enabled or e.closes_at<=now() or not exists(select 1 from public.gallery_events where id=e.event_id and active and deleted_at is null and purge_started_at is null) then raise exception 'Event closed' using errcode='PT403'; end if;
 if e.studio_user is not null and e.studio_user is distinct from p_user then raise exception 'Sign in to your workspace' using errcode='PT403'; end if;
 select * into s from public.gallery_guest_sessions where token_hash=p_token;
 if found then
  if s.event_id<>e.event_id or s.link_hash<>p_link then raise exception 'Session unavailable' using errcode='PT403'; end if;
  return s;
 end if;
 if e.sessions>=10000 then raise exception 'Event session limit reached' using errcode='PT429'; end if;
 insert into public.gallery_guest_sessions(event_id,token_hash,link_hash,user_id) values(e.event_id,p_token,p_link,p_user) returning * into s;
 update public.gallery_experiences set sessions=sessions+1 where event_id=e.event_id;
 return s;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_finish_purge(target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e gallery_events; inventory jsonb;
begin
 select * into e from gallery_events where id=target for update;
 if not found then return jsonb_build_object('deleted',true); end if;
 if e.purge_started_at is null or e.deleted_at is null or e.active then raise exception 'Deletion has not started'; end if;
 inventory=gallery_purge_inventory(target);
 if (inventory->>'fileCount')::bigint<>0 or (inventory->>'blockingRequests')::bigint<>0 then raise exception 'Files or open requests remain'; end if;
 delete from gallery_selections where event_id=target;
 delete from gallery_invitations where event_id=target;
 delete from gallery_access where event_id=target;
 delete from gallery_requests where event_id=target;
 delete from gallery_photos where event_id=target;
 delete from gallery_events where id=target;
 return jsonb_build_object('deleted',true);
end; $function$

CREATE OR REPLACE FUNCTION public.gallery_guest_delete_begin(p_event uuid, p_photo uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_guest_uploads; p public.gallery_photos;
begin
 select * into u from public.gallery_guest_uploads where photo_id=p_photo for update;
 if not found or u.status not in ('rejected','deleting') then raise exception 'Only rejected photos can be deleted'; end if;
 select * into p from public.gallery_photos where id=p_photo and event_id=p_event for update;
 if not found then raise exception 'Photo unavailable'; end if;
 if exists(select 1 from public.gallery_print_jobs where source_photo_id=p_photo) or exists(select 1 from public.gallery_requests r cross join lateral jsonb_array_elements(r.items) i where r.event_id=p_event and i->>'photoId'=p_photo::text) then raise exception 'Photo linked to printing or an order'; end if;
 update public.gallery_guest_uploads set status='deleting' where photo_id=p_photo;
 update public.gallery_photos set ready=false,hidden=true where id=p_photo;
 return jsonb_build_object('original_key',p.original_key,'preview_key',p.preview_key);
end $function$

CREATE OR REPLACE FUNCTION public.gallery_guest_finish(p_token text, p_request uuid, p_preview_bytes integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_guest_sessions; u public.gallery_guest_uploads; approval boolean;
begin
 s=public.gallery_experience_check(p_token);
 select * into u from public.gallery_guest_uploads where session_id=s.id and request_id=p_request for update;
 if not found then raise exception 'Upload unavailable'; end if;
 if u.status<>'uploading' then return u.status; end if;
 if p_preview_bytes not between 1 and 1048576 then raise exception 'Invalid preview'; end if;
 select not moderation into approval from public.gallery_experiences where event_id=s.event_id;
 update public.gallery_photos set ready=true,hidden=not approval,original_bytes=u.bytes,preview_bytes=p_preview_bytes where id=u.photo_id;
 update public.gallery_guest_uploads set status=case when approval then 'approved' else 'pending' end where photo_id=u.photo_id;
 return case when approval then 'approved' else 'pending' end;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_guest_queue(p_event uuid, p_photo uuid, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_guest_uploads; existing public.gallery_print_jobs;
begin
 if p_request is null then raise exception 'Queue request required'; end if;
 select u1.* into u from public.gallery_guest_uploads u1 join public.gallery_photos p on p.id=u1.photo_id
 where p.id=p_photo and p.event_id=p_event and p.ready and not p.hidden for update of u1;
 if not found or u.status<>'approved' then raise exception 'Approve this photo before printing'; end if;
 insert into public.gallery_print_jobs(id,event_id,source_photo_id,quantity) values(p_request,p_event,p_photo,1) on conflict(id) do nothing;
 select * into existing from public.gallery_print_jobs where id=p_request;
 if existing.event_id<>p_event or existing.source_photo_id<>p_photo or existing.source_request_id is not null then raise exception 'Queue request conflict'; end if;
 return existing.id;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_guest_reserve(p_token text, p_request uuid, p_filename text, p_mime text, p_bytes integer)
 RETURNS gallery_photos
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_guest_sessions; e public.gallery_experiences; u public.gallery_guest_uploads; p public.gallery_photos; ext text;
begin
 s=public.gallery_experience_check(p_token);
 select * into e from public.gallery_experiences where event_id=s.event_id for update;
 if e.token_hash<>s.link_hash or not e.enabled or e.closes_at<=now() then raise exception 'Event closed' using errcode='PT403'; end if;
 select * into s from public.gallery_guest_sessions where id=s.id for update;
 select * into u from public.gallery_guest_uploads where session_id=s.id and request_id=p_request;
 if found then
  if u.status='deleting' then raise exception 'Photo deletion in progress' using errcode='PT409'; end if;
  select * into p from public.gallery_photos where id=u.photo_id;
  if u.mime<>p_mime or u.bytes<>p_bytes or p.filename<>p_filename then raise exception 'Upload changed' using errcode='PT409'; end if;
  return p;
 end if;
 if s.reserved>=e.guest_limit or e.reserved>=e.event_limit then raise exception 'Upload limit reached' using errcode='PT429'; end if;
 if length(p_filename) not between 1 and 180 or p_bytes not between 1 and 15728640 then raise exception 'Invalid photo'; end if;
 ext=case p_mime when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' else null end;
 if ext is null then raise exception 'Unsupported photo'; end if;
 p.id=gen_random_uuid();
 insert into public.gallery_photos(id,event_id,filename,original_key,preview_key,position,ready,hidden)
 values(p.id,s.event_id,p_filename,s.event_id::text||'/'||p.id::text||'/original.'||ext,s.event_id::text||'/'||p.id::text||'/preview.jpg',extract(epoch from now())::integer,false,true) returning * into p;
 insert into public.gallery_guest_uploads values(s.id,p_request,p.id,p_mime,p_bytes,'uploading');
 update public.gallery_guest_sessions set reserved=reserved+1 where id=s.id;
 update public.gallery_experiences set reserved=reserved+1 where event_id=e.event_id;
 return p;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_guest_review(p_event uuid, p_photo uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_guest_uploads;
begin
 select u1.* into u from public.gallery_guest_uploads u1 join public.gallery_photos p on p.id=u1.photo_id where p.id=p_photo and p.event_id=p_event and p.ready for update of u1;
 if not found or p_action not in ('approve','reject','print') then raise exception 'Photo unavailable'; end if;
 if p_action='print' then
  if u.status<>'approved' then raise exception 'Approve this photo before printing'; end if;
  insert into public.gallery_print_jobs(id,event_id) values(p_photo,p_event) on conflict(id) do nothing;
 else
  if p_action='reject' and exists(select 1 from public.gallery_print_jobs where source_photo_id=p_photo and status='printing') then raise exception 'Resolve the reserved print first'; end if;
  update public.gallery_guest_uploads set status=case when p_action='approve' then 'approved' else 'rejected' end where photo_id=p_photo;
  update public.gallery_photos set hidden=p_action='reject' where id=p_photo;
  -- Approval queues one magnet only for event uploads, never unpaid commerce work.
  -- The upload row lock serializes review and manual queue requests.
  if p_action='approve' and u.status<>'approved'
   and exists(select 1 from public.gallery_experiences where event_id=p_event and studio_user is null and not upload_later)
   and not exists(select 1 from public.gallery_print_jobs where source_photo_id=p_photo) then
   insert into public.gallery_print_jobs(id,event_id,source_photo_id,quantity)
    values(p_photo,p_event,p_photo,1) on conflict(id) do nothing;
  end if;
  if p_action='reject' then update public.gallery_print_jobs set status='held',version=version+1 where source_photo_id=p_photo and status='pending'; end if;
 end if;
 return p_action;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_helper_authorize(p_hash text, p_batch uuid, p_job uuid, p_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; j public.gallery_print_jobs; n integer=0;
begin
 s=public.gallery_station_check(p_hash,'print');
 if (p_batch is null)=(p_job is null) then raise exception 'Invalid reservation'; end if;
 for j in select * from public.gallery_print_jobs where event_id=s.event_id and (letter_batch_id=p_batch or id=p_job) order by id for update loop
  if j.status<>'printing' or (p_job is not null and j.version is distinct from p_version) then raise exception 'Reservation changed'; end if;
  if p_batch is not null and j.sheet_profile<>'8x12' then raise exception 'Wrong paper profile'; end if;
  if not exists(select 1 from public.gallery_photos where id=j.source_photo_id and event_id=s.event_id and ready and not hidden) then raise exception 'Photo unavailable'; end if;
  -- Re-run the paid-order guard immediately before local printer submission.
  update public.gallery_print_jobs set status=status where id=j.id;
  n=n+1;
 end loop;
 if n=0 then raise exception 'Reservation unavailable'; end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_helper_complete(p_hash text, p_batch uuid, p_job uuid, p_version integer, p_spooler text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations;n integer;
begin
 s=public.gallery_station_check(p_hash,'print');
 if (p_batch is null)=(p_job is null) or p_spooler !~ '^[A-Za-z0-9_.-]+-[0-9]+$' or length(p_spooler)>180 then raise exception 'Invalid completion'; end if;
 if p_batch is not null then
  update public.gallery_print_jobs set status='printed',completion_source='computer',spooler_job=p_spooler,version=version+1,updated_at=now() where event_id=s.event_id and letter_batch_id=p_batch and status='printing';
 else
  update public.gallery_print_jobs set status='printed',completion_source='computer',spooler_job=p_spooler,version=version+1,updated_at=now() where event_id=s.event_id and id=p_job and version=p_version and letter_batch_id is null and status='printing';
 end if;
 get diagnostics n=row_count;
 if n=0 and not exists(select 1 from public.gallery_print_jobs where event_id=s.event_id and (letter_batch_id=p_batch or id=p_job) and status='printed' and completion_source='computer' and spooler_job=p_spooler) then raise exception 'Queue changed' using errcode='PT409'; end if;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_helper_control(p_event uuid, p_action text, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare h public.gallery_print_helpers; r public.gallery_helper_runs; digest text; j public.gallery_print_jobs; item jsonb; sheet public.gallery_helper_sheets;
begin
 perform 1 from public.gallery_events where id=p_event for update;
 select * into h from public.gallery_print_helpers where id=(p_body->>'helperId')::uuid and event_id=p_event for update;
 if not found then raise exception 'Helper unavailable';end if;
 if p_action in ('start','pause','flush','end','revoke') then
  if p_action in ('start','end') and not exists(select 1 from public.gallery_stations where id=h.station_id and not revoked and expires_at>now()) then raise exception 'Pair a new helper; this credential expired or was disconnected';end if;
  if p_action='start' and (not h.paired or h.printer is null or exists(select 1 from public.gallery_helper_runs hr join public.gallery_helper_sheets hs on hs.run_id=hr.id where hr.helper_id=h.id and hr.state='active' and hs.state='attention')) then raise exception 'Pair, calibrate, and resolve attention first';end if;
  update public.gallery_print_helpers set mode=case p_action when 'start' then 'running' when 'pause' then 'paused' when 'end' then 'ending' when 'revoke' then 'ended' else mode end,
   flush=case when p_action in ('flush','end') then true else flush end,attention=case when p_action='start' then null else attention end where id=h.id;
  if p_action='revoke' then update public.gallery_stations set revoked=true where id=h.station_id;end if;
 elsif p_action='settings' then
  if h.mode not in ('paused','ended') then raise exception 'Pause before changing settings';end if;
  update public.gallery_print_helpers set partial_seconds=(p_body->>'partialSeconds')::integer where id=h.id;
 elsif p_action='confirm-sheet' then
  select * into r from public.gallery_helper_runs where id=(p_body->>'runId')::uuid and helper_id=h.id and state='active' for update;
  if not found or p_body->>'confirm' is distinct from 'true' then raise exception 'Confirm the physical sheet first';end if;
  select * into sheet from public.gallery_helper_sheets where id=(p_body->>'sheetId')::uuid and run_id=r.id for update;
  if not found or sheet.spooler_job is distinct from p_body->>'spoolerJob' or sheet.spooler_job is null then raise exception 'Exact sheet receipt required';end if;
  if sheet.state='operator' then return jsonb_build_object('saved',true);end if;
  if sheet.state<>'awaiting_confirmation' then raise exception 'This sheet is not waiting for confirmation';end if;
  update public.gallery_helper_sheets set state='operator',error=null,updated_at=now() where id=sheet.id;
  if not exists(select 1 from public.gallery_helper_sheets where run_id=r.id and state not in ('completed','operator')) then
   update public.gallery_print_jobs set status='printed',print_run_id=null,completion_source='operator',version=version+1,updated_at=now() where print_run_id=r.id and event_id=p_event;
   update public.gallery_print_runs set status='printed',finished_at=now() where id=r.id;
   update public.gallery_helper_runs set state='completed' where id=r.id;
   update public.gallery_print_helpers set mode='ended' where id=h.id and mode='ending';
  end if;
 elsif p_action='resolve' then
  select * into r from public.gallery_helper_runs where id=(p_body->>'runId')::uuid and helper_id=h.id and state='active' for update;
  if not found or p_body->>'confirm'<>'true' or p_body->>'outcome' not in ('printed','release') then raise exception 'Confirm the physical outcome first';end if;
  if p_body->>'outcome'='release' and exists(select 1 from public.gallery_helper_sheets where run_id=r.id and state<>'preparing') then raise exception 'Submission may have happened. Do not release this run; inspect and finish its remaining sheets manually.';end if;
  select token_hash into digest from public.gallery_stations where id=h.station_id;
  -- Owner reconciliation remains available after the helper expires or is revoked.
  update public.gallery_print_jobs set status=case when p_body->>'outcome'='printed' then 'printed' else 'pending' end,print_run_id=null,completion_source='operator',version=version+1,updated_at=now()
   where print_run_id=r.id and event_id=p_event;
  update public.gallery_print_runs set status=case when p_body->>'outcome'='printed' then 'printed' else 'released' end,finished_at=now() where id=r.id;
  update public.gallery_helper_runs set state=case when p_body->>'outcome'='printed' then 'operator' else 'released' end where id=r.id;
  update public.gallery_helper_sheets set state=case when p_body->>'outcome'='printed' then 'operator' else 'released' end,updated_at=now() where run_id=r.id and state not in ('completed','operator');
  update public.gallery_print_helpers set mode='paused',attention=null where id=h.id;
 elsif p_action='reprint' then
  select hs.* into sheet from public.gallery_helper_sheets hs join public.gallery_helper_runs hr on hr.id=hs.run_id
   where hs.id=(p_body->>'sheetId')::uuid and hr.helper_id=h.id and hr.state in ('completed','operator');
  if not found or sheet.state not in ('completed','operator') or length(trim(coalesce(p_body->>'reason',''))) not between 3 and 200 then raise exception 'Choose a completed sheet and enter a reprint reason';end if;
  if exists(select 1 from public.gallery_helper_reprints where id=(p_body->>'requestId')::uuid and event_id=p_event and sheet_id=sheet.id) then return jsonb_build_object('saved',true);end if;
  if p_body ? 'jobIds' and (jsonb_array_length(p_body->'jobIds')=0 or exists(select 1 from jsonb_array_elements_text(p_body->'jobIds') chosen where not exists(select 1 from jsonb_array_elements(sheet.items) i where i->>'id'=chosen))) then raise exception 'Selected photos must belong to this sheet';end if;
  insert into public.gallery_helper_reprints(id,event_id,sheet_id,reason) values((p_body->>'requestId')::uuid,p_event,sheet.id,trim(p_body->>'reason'));
  for item in select value from jsonb_array_elements(sheet.items) loop
   if p_body ? 'jobIds' and not (p_body->'jobIds' @> jsonb_build_array(item->>'id')) then continue;end if;
   select * into j from public.gallery_print_jobs where id=(item->>'id')::uuid and event_id=p_event;
   if not found or j.source_request_id is not null or j.source_order_upload_id is not null then raise exception 'This first automatic reprint flow supports event photos; use paid-order review for commerce reprints';end if;
   insert into public.gallery_print_jobs(id,event_id,source_photo_id,quantity,x,y,zoom,template,reprint_of)
    values(gen_random_uuid(),p_event,j.source_photo_id,1,(item->>'x')::numeric,(item->>'y')::numeric,(item->>'zoom')::numeric,item->'template',j.id);
  end loop;
 else raise exception 'Invalid owner action';end if;
 insert into public.gallery_activity_log(source,event_id,action,outcome,subject_reference,details) values('backend',p_event,'helper.'||p_action,'committed',h.id::text,p_body-array['token','code']);
 return jsonb_build_object('saved',true);
end $function$

CREATE OR REPLACE FUNCTION public.gallery_helper_pair(p_code text, p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare h public.gallery_print_helpers;
begin
 if p_token !~ '^[a-f0-9]{64}$' then raise exception 'Invalid credential';end if;
 update public.gallery_print_helpers set paired=true,pair_hash=null where pair_hash=p_code and not paired and pair_expires_at>now() returning * into h;
 if not found then raise exception 'Pairing code expired or already used' using errcode='PT403';end if;
 update public.gallery_stations set token_hash=p_token where id=h.station_id and not revoked and expires_at>now();
 if not found then raise exception 'Pairing unavailable' using errcode='PT403';end if;
 return h.id;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_helper_step(p_hash text, p_action text, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare st public.gallery_stations; h public.gallery_print_helpers; r public.gallery_helper_runs; sh public.gallery_helper_sheets;
 data jsonb; item jsonb; copies jsonb='[]'; chunk jsonb; n integer; oldest timestamptz; idx integer=0; target uuid; desired text; capacity integer; paper text;
begin
 st=public.gallery_station_check(p_hash,'print');
 perform 1 from public.gallery_events where id=st.event_id for update;
 select * into h from public.gallery_print_helpers where station_id=st.id and paired for update;
 if not found then raise exception 'Helper unavailable' using errcode='PT403';end if;
 capacity=case h.printer->>'id' when 'photo-4x6-single' then 1 when 'letter-four' then 4 else 6 end;paper=case capacity when 1 then '4x6' when 4 then 'letter' else '8x12' end;
 update public.gallery_print_helpers set heartbeat_at=now() where id=h.id;
 if p_action='heartbeat' then return jsonb_build_object('mode',h.mode,'attention',h.attention,'eventId',h.event_id,'confirmedSheets',(select coalesce(jsonb_agg(hs.id),'[]'::jsonb) from public.gallery_helper_sheets hs join public.gallery_helper_runs hr on hr.id=hs.run_id where hr.id=(p_body->>'runId')::uuid and hr.helper_id=h.id and hs.state='operator'),'runState',(select state from public.gallery_helper_runs where id=(p_body->>'runId')::uuid and helper_id=h.id));end if;
 select * into r from public.gallery_helper_runs where helper_id=h.id and state='active' for update;
 if p_action='claim' then
  if r.id is not null then
   return jsonb_build_object('recovery',true,'runId',r.id,'fence',r.fence,'profile',r.profile,'sheets',(select jsonb_agg(to_jsonb(x) order by sheet_index) from public.gallery_helper_sheets x where run_id=r.id));
  end if;
  if h.mode not in ('running','ending') or h.attention is not null then return jsonb_build_object('waiting',true);end if;
  if exists(select 1 from public.gallery_helper_runs x join public.gallery_print_runs pr on pr.id=x.id where pr.event_id=h.event_id and x.state='active') then raise exception 'Another helper owns the reserved run' using errcode='PT409';end if;
  select coalesce(sum(quantity),0),min(created_at) into n,oldest from public.gallery_print_jobs j
   where event_id=h.event_id and status='pending' and exists(select 1 from public.gallery_photos p where p.id=j.source_photo_id and p.ready and not p.hidden);
  if n=0 then
   if h.mode='ending' then update public.gallery_print_helpers set mode='ended' where id=h.id;end if;
   return jsonb_build_object('waiting',true,'copies',0);
  end if;
  if n<capacity and not h.flush and h.mode<>'ending' and (h.partial_seconds=0 or oldest+make_interval(secs=>h.partial_seconds)>now()) then return jsonb_build_object('waiting',true,'copies',n);end if;
  if h.printer is null then raise exception 'Calibrated printer profile required';end if;
  target=(p_body->>'requestId')::uuid;
  data=public.gallery_print_run(p_hash,'claim',target,paper);
  if data->'run' is null or data->'run'='null'::jsonb then return jsonb_build_object('waiting',true);end if;
  target=(data->'run'->>'id')::uuid;
  insert into public.gallery_helper_runs(id,helper_id,profile,allow_partial) values(target,h.id,h.printer,h.flush or h.mode='ending') returning * into r;
  for item in select value from jsonb_array_elements(data->'run'->'jobs') loop
   for n in 1..(item->>'quantity')::integer loop copies=copies||jsonb_build_array(item||coalesce(nullif(item->'print_crop','null'::jsonb),'{}'::jsonb)||jsonb_build_object('quantity',1));end loop;
  end loop;
  for n in 0..jsonb_array_length(copies)-1 by capacity loop
   select jsonb_agg(value order by ord) into chunk from jsonb_array_elements(copies) with ordinality a(value,ord) where ord>n and ord<=n+capacity;
   insert into public.gallery_helper_sheets(run_id,sheet_index,items) values(r.id,idx,chunk);idx=idx+1;
  end loop;
  update public.gallery_print_helpers set flush=false where id=h.id;
  return jsonb_build_object('runId',r.id,'fence',r.fence,'profile',r.profile,'sheets',(select jsonb_agg(to_jsonb(x) order by sheet_index) from public.gallery_helper_sheets x where run_id=r.id));
 end if;
 if r.id is null and p_action='report' and p_body->>'state'='completed' and exists(
  select 1 from public.gallery_helper_runs hr join public.gallery_helper_sheets hs on hs.run_id=hr.id where hr.helper_id=h.id and hr.id=(p_body->>'runId')::uuid and hr.fence=(p_body->>'fence')::uuid
   and hs.id=(p_body->>'sheetId')::uuid and hs.attempt_id=(p_body->>'attemptId')::uuid and hs.spooler_job=p_body->>'spoolerJob' and hs.state='completed'
 ) then return jsonb_build_object('saved',true);end if;
 if r.id is null or r.id is distinct from (p_body->>'runId')::uuid or r.fence is distinct from (p_body->>'fence')::uuid then raise exception 'Reservation fence changed' using errcode='PT409';end if;
 if p_action='renew' then
  update public.gallery_helper_runs set lease_until=now()+interval '90 seconds' where id=r.id;
  return jsonb_build_object('renewed',true);
 end if;
 select * into sh from public.gallery_helper_sheets where id=(p_body->>'sheetId')::uuid and run_id=r.id for update;
 if not found then raise exception 'Sheet unavailable' using errcode='PT409';end if;
 if p_action='submit' then
  if h.mode not in ('running','ending') or h.attention is not null or r.lease_until<=now() then raise exception 'Automatic printing paused or lease expired' using errcode='PT409';end if;
  if sh.state='submitting' and sh.attempt_id=(p_body->>'attemptId')::uuid and sh.artifact_hash=p_body->>'sha256' then return jsonb_build_object('authorized',true);end if;
  if sh.state<>'preparing' or exists(select 1 from public.gallery_helper_sheets where run_id=r.id and sheet_index<sh.sheet_index and state not in ('completed','operator')) then raise exception 'Resolve earlier sheet first' using errcode='PT409';end if;
  if jsonb_array_length(sh.items)<capacity and not r.allow_partial and not h.flush and h.mode<>'ending' then
   select min((value->>'created_at')::timestamptz) into oldest from jsonb_array_elements(sh.items);
   if h.partial_seconds=0 or oldest+make_interval(secs=>h.partial_seconds)>now() then return jsonb_build_object('waiting',true,'authorized',false);end if;
  end if;
  if h.flush then update public.gallery_helper_runs set allow_partial=true where id=r.id;update public.gallery_print_helpers set flush=false where id=h.id;end if;
  if coalesce(p_body->>'sha256','') !~ '^[a-f0-9]{64}$' or p_body->>'attemptId' is null then raise exception 'Artifact required';end if;
  perform public.gallery_print_run_manual(p_hash,'authorize',r.id,paper);
  update public.gallery_helper_sheets set state='submitting',attempt_id=(p_body->>'attemptId')::uuid,artifact_hash=p_body->>'sha256',updated_at=now() where id=sh.id;
  return jsonb_build_object('authorized',true);
 end if;
 if p_action='report' then
  desired=p_body->>'state';
  if sh.attempt_id is distinct from (p_body->>'attemptId')::uuid then raise exception 'Attempt changed' using errcode='PT409';end if;
  if desired='attention' then
   update public.gallery_helper_sheets set state='attention',error=left(p_body->>'error',300),updated_at=now() where id=sh.id and state not in ('completed','operator');
   update public.gallery_print_helpers set mode='paused',attention='Printer needs attention. Inspect the reserved sheet before continuing.' where id=h.id;
  elsif desired in ('submitted','completed','awaiting_confirmation') then
   if coalesce(p_body->>'spoolerJob','') !~ '^[A-Za-z0-9_.-]+-[0-9]+$' then raise exception 'Exact spooler job required';end if;
   if sh.spooler_job is not null and sh.spooler_job<>p_body->>'spoolerJob' then raise exception 'Spooler job changed';end if;
   if sh.state in ('completed','operator') then return jsonb_build_object('saved',true);end if;
   if sh.state not in ('submitting','submitted','awaiting_confirmation') then raise exception 'Inspect uncertain outcome' using errcode='PT409';end if;
   update public.gallery_helper_sheets set state=desired,error=case when desired='awaiting_confirmation' then 'Inspect this sheet and confirm it in the dashboard.' else null end,spooler_job=p_body->>'spoolerJob',updated_at=now() where id=sh.id;
   if desired='completed' and not exists(select 1 from public.gallery_helper_sheets where run_id=r.id and state not in ('completed','operator')) then
    perform public.gallery_print_run_manual(p_hash,'printed',r.id,paper);
    update public.gallery_print_jobs set completion_source=case when exists(select 1 from public.gallery_helper_sheets where run_id=r.id and state='operator') then 'operator' else 'computer' end where id in (select unnest(job_ids) from public.gallery_print_runs where id=r.id);
    update public.gallery_helper_runs set state='completed' where id=r.id;
    update public.gallery_print_helpers set mode='ended' where id=h.id and mode='ending';
   end if;
  else raise exception 'Invalid report';end if;
  return jsonb_build_object('saved',true);
 end if;
 raise exception 'Invalid helper action';
end $function$

CREATE OR REPLACE FUNCTION public.gallery_invitation_email_claim(p_event uuid, p_email text, p_resend boolean, p_claim uuid, p_expires_at timestamp with time zone, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 invitation public.gallery_invitations;
 delivery public.gallery_invitation_emails;
 new_message boolean;
begin
 select * into invitation from public.gallery_invitations where event_id=p_event and email=p_email for update;
 if not found or invitation.revoked or invitation.expires_at<=now()
  or not exists(select 1 from public.gallery_events where id=p_event and active and deleted_at is null)
 then return jsonb_build_object('status','unavailable'); end if;
 if invitation.expires_at is distinct from p_expires_at then return jsonb_build_object('status','changed'); end if;
 if p_claim is null or p_payload is null or p_payload#>>'{to,0}' is distinct from p_email then raise exception 'Invalid email preparation'; end if;
 select * into delivery from public.gallery_invitation_emails where event_id=p_event and email=p_email for update;
 if found then
  if delivery.lease_until>now() then return jsonb_build_object('status','busy'); end if;
  if delivery.status='accepted' and delivery.expires_at=invitation.expires_at and not p_resend then return jsonb_build_object('status','already_accepted'); end if;
  -- Never reuse an expired provider idempotency key for an ambiguous attempt.
  if delivery.status<>'accepted' and (delivery.first_attempt_at<now()-interval '23 hours' or delivery.expires_at<>invitation.expires_at)
   then return jsonb_build_object('status','review'); end if;
  if delivery.last_attempt_at>now()-interval '60 seconds' then return jsonb_build_object('status','cooldown'); end if;
  if delivery.window_started_at>now()-interval '1 hour' and delivery.attempts>=3 then return jsonb_build_object('status','limited'); end if;
  new_message:=delivery.status='accepted';
  update public.gallery_invitation_emails set
   version=case when new_message then gen_random_uuid() else version end,
   expires_at=case when new_message then invitation.expires_at else expires_at end,
   payload=case when new_message then p_payload else payload end,
   first_attempt_at=case when new_message then now() else first_attempt_at end,
   attempts=case when window_started_at<=now()-interval '1 hour' then 1 else attempts+1 end,
   window_started_at=case when window_started_at<=now()-interval '1 hour' then now() else window_started_at end,
   status='pending',claim=p_claim,lease_until=now()+interval '60 seconds',last_attempt_at=now(),accepted_at=null,provider_id=null
  where event_id=p_event and email=p_email returning * into delivery;
 else
  insert into public.gallery_invitation_emails(event_id,email,expires_at,payload,claim,lease_until,last_attempt_at,attempts)
  values(p_event,p_email,invitation.expires_at,p_payload,p_claim,now()+interval '60 seconds',now(),1) returning * into delivery;
 end if;
 return jsonb_build_object('status','send','delivery',jsonb_build_object('version',delivery.version,'payload',delivery.payload));
end;
$function$

CREATE OR REPLACE FUNCTION public.gallery_later_check(p_id uuid)
 RETURNS gallery_order_uploads
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_order_uploads; p public.gallery_payments; expected public.gallery_later_products;
begin
 select * into u from public.gallery_order_uploads where id=p_id;
 if not found or u.expires_at<=now() then raise exception 'Upload link unavailable' using errcode='PT403';end if;
 select * into p from public.gallery_payments where order_id=u.order_id for share;
 select * into expected from public.gallery_later_products where variant_id=u.variant_id;
 if u.required_count>200 or p.financial_status<>'paid' or p.cancelled or p.refund_activity or p.is_test or p.currency<>'USD'
 or not exists(select 1 from jsonb_array_elements(p.lines) l where l->>'line_id'=u.line_id and l->>'variant_id'=u.variant_id
 and l->>'upload_later'='true' and (l->>'quantity')::integer=u.quantity and (l->>'unit_cents')::integer=expected.unit_cents)
 or not exists(select 1 from public.gallery_events where id=u.event_id and active and deleted_at is null and purge_started_at is null)
 then raise exception 'Order needs review' using errcode='PT403';end if;
 return u;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_later_email_claim(p_id uuid, p_claim uuid, p_resend boolean DEFAULT false)
 RETURNS gallery_order_uploads
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_order_uploads; recipient text;
begin
 select * into u from public.gallery_order_uploads where id=p_id for update;
 perform public.gallery_later_check(p_id);
 if u.status<>'awaiting_photos' then return null;end if;
 if u.email_lease_until>now() then raise exception 'Email is being sent' using errcode='PT409';end if;
 if u.email_sent_at is not null and not p_resend then return null;end if;
 if p_resend and u.email_attempted_at>now()-interval '1 minute' then raise exception 'Wait before resending' using errcode='PT429';end if;
 -- Avoid automatic ambiguous retries after provider idempotency expires.
 if not p_resend and u.email_attempted_at<now()-interval '23 hours' then raise exception 'Owner resend required' using errcode='PT409';end if;
 select customer_email into recipient from public.gallery_payments where order_id=u.order_id;
 if recipient is null then raise exception 'Order has no email' using errcode='PT422';end if;
 update public.gallery_order_uploads set email_version=email_version+case when p_resend then 1 else 0 end,
 email_claim=p_claim,email_lease_until=now()+interval '1 minute',email_error=null,
 email_recipient=case when p_resend or email_recipient is null then recipient else email_recipient end,
 email_attempted_at=case when p_resend or email_attempted_at is null then now() else email_attempted_at end
 where id=p_id returning * into u;
 return u;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_later_link(p_id uuid, p_hash text)
 RETURNS gallery_order_uploads
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_order_uploads;
begin
 u=public.gallery_later_check(p_id);
 if p_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid link';end if;
 update public.gallery_order_uploads set token_hash=p_hash where id=p_id returning * into u;
 update public.gallery_experiences set token_hash=p_hash,enabled=true,closes_at=u.expires_at where event_id=u.event_id;
 return u;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_later_print_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_order_uploads;
begin
 if new.source_order_upload_id is not null then
  if new.source_request_id is not null then raise exception 'Ambiguous order';end if;
  if tg_op='INSERT' or new.status='printing' then
   u=public.gallery_later_check(new.source_order_upload_id);
   if u.event_id<>new.event_id or u.status not in ('submitted','queued','completed') then raise exception 'Submit photos first' using errcode='PT409';end if;
   if not exists(select 1 from jsonb_array_elements(u.items) i where i->>'photoId'=new.source_photo_id::text and
    (i->>'quantity')::integer=new.quantity and (i->>'x')::numeric=new.x and (i->>'y')::numeric=new.y and (i->>'zoom')::numeric=new.zoom) then raise exception 'Submitted crop is fixed';end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_later_produce(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.gallery_order_uploads; item jsonb; t jsonb; n integer=0;
begin
 select * into u from public.gallery_order_uploads where id=p_id for update;
 u=public.gallery_later_check(p_id);
 if u.status not in ('submitted','queued') then raise exception 'Submit photos first' using errcode='PT409';end if;
 select template into t from public.gallery_magnet_templates where event_id=u.event_id;
 for item in select value from jsonb_array_elements(u.items) loop
  if not exists(select 1 from public.gallery_photos where id=(item->>'photoId')::uuid and event_id=u.event_id and ready and not hidden) then raise exception 'Photo unavailable';end if;
  insert into public.gallery_print_jobs(id,event_id,source_photo_id,source_order_upload_id,quantity,x,y,zoom,template)
   values(gen_random_uuid(),u.event_id,(item->>'photoId')::uuid,u.id,(item->>'quantity')::integer,(item->>'x')::numeric,(item->>'y')::numeric,(item->>'zoom')::numeric,
   coalesce(t,'{"enabled":false,"photoCutInches":2.5,"cutInches":3.25}'::jsonb))
   on conflict(source_order_upload_id,source_photo_id) where source_order_upload_id is not null do nothing;
  if found then n=n+1;end if;
 end loop;
 update public.gallery_order_uploads set status='queued' where id=u.id;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_later_save(p_session text, p_items jsonb, p_revision integer, p_submit boolean DEFAULT false)
 RETURNS gallery_order_uploads
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_guest_sessions; u public.gallery_order_uploads; item jsonb; seen uuid[]='{}'; photo uuid; total integer=0;
begin
 s=public.gallery_experience_check(p_session);
 select * into u from public.gallery_order_uploads where event_id=s.event_id for update;
 if not found then raise exception 'Order unavailable' using errcode='PT403';end if;
 perform public.gallery_later_check(u.id);
 if u.status<>'awaiting_photos' then
  if p_submit and p_items=u.items then
   if u.status='submitted' then
    perform public.gallery_later_produce(u.id);
    select * into u from public.gallery_order_uploads where id=u.id;
   end if;
   return u;
  end if;
  raise exception 'Photos already submitted' using errcode='PT409';
 end if;
 if u.revision<>p_revision then raise exception 'Selection changed. Reload saved photos.' using errcode='PT409';end if;
 if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>200 or octet_length(p_items::text)>65536 then raise exception 'Invalid selection';end if;
 for item in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(item)<>'object' or not(item ?& array['photoId','quantity','x','y','zoom']) or (item-array['photoId','quantity','x','y','zoom'])<>'{}'::jsonb then raise exception 'Invalid photo';end if;
  photo=(item->>'photoId')::uuid;
  if photo=any(seen) or not exists(select 1 from public.gallery_photos where id=photo and event_id=u.event_id and ready and not hidden) then raise exception 'Photo unavailable';end if;
  if jsonb_typeof(item->'quantity')<>'number' or (item->>'quantity')::numeric not between 1 and 12 or trunc((item->>'quantity')::numeric)<>(item->>'quantity')::numeric
   or jsonb_typeof(item->'x')<>'number' or jsonb_typeof(item->'y')<>'number' or jsonb_typeof(item->'zoom')<>'number'
   or (item->>'x')::numeric not between 0 and 100 or (item->>'y')::numeric not between 0 and 100 or (item->>'zoom')::numeric not between 1 and 3 then raise exception 'Invalid crop or copies';end if;
  total=total+(item->>'quantity')::integer;seen=array_append(seen,photo);
 end loop;
 if total>u.required_count or (p_submit and total<>u.required_count) then raise exception 'Choose the purchased number of magnets' using errcode='PT422';end if;
 update public.gallery_order_uploads set items=p_items,revision=revision+1,
 status=case when p_submit then 'submitted' else status end,submitted_at=case when p_submit then now() else submitted_at end
 where id=u.id returning * into u;
 if p_submit then
  perform public.gallery_later_produce(u.id);
  select * into u from public.gallery_order_uploads where id=u.id;
 end if;
 return u;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_letter_finish(p_hash text, p_batch uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; n integer;
begin
 s=public.gallery_station_check(p_hash,'print');
 perform 1 from public.gallery_events where id=s.event_id for update;
 if p_action is null or p_action not in ('printed','release') then raise exception 'Invalid batch action' using errcode='PT409'; end if;
 perform 1 from public.gallery_print_jobs where event_id=s.event_id and letter_batch_id=p_batch order by id for update;
 if p_action='printed' then
  update public.gallery_print_jobs set status='printed',version=version+1,updated_at=now() where event_id=s.event_id and letter_batch_id=p_batch and status='printing';
 else
  update public.gallery_print_jobs set status='pending',letter_batch_id=null,letter_slot=null,version=version+1,updated_at=now() where event_id=s.event_id and letter_batch_id=p_batch and status='printing';
 end if;
 get diagnostics n=row_count;
 if n>0 then
  insert into public.gallery_activity_log(source,actor_user_id,event_id,action,outcome,subject_reference,details)
  values('backend',s.actor_id,s.event_id,'station.letter.'||p_action,'committed',p_batch::text,jsonb_build_object('photos',n));
 end if;
 return jsonb_build_object('updated',n);
end $function$

CREATE OR REPLACE FUNCTION public.gallery_order_produce(p_request uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.gallery_requests; item jsonb; n integer=0; t jsonb;
begin
 select * into r from public.gallery_requests where id=p_request for update;
 if not found then raise exception 'Order unavailable'; end if;
 if not exists(select 1 from public.gallery_events where id=r.event_id and active and deleted_at is null and purge_started_at is null) then raise exception 'Event unavailable'; end if;
 select template into t from public.gallery_magnet_templates where event_id=r.event_id;
 for item in select value from jsonb_array_elements(r.items) loop
  if not exists(select 1 from public.gallery_photos where id=(item->>'photoId')::uuid and event_id=r.event_id and ready and not hidden) then raise exception 'Photo unavailable'; end if;
  if not exists(select 1 from public.gallery_print_jobs where source_request_id=r.id and source_photo_id=(item->>'photoId')::uuid) then
   insert into public.gallery_print_jobs(id,event_id,source_photo_id,source_request_id,quantity,x,y,zoom,template)
   values(gen_random_uuid(),r.event_id,(item->>'photoId')::uuid,r.id,(item->>'quantity')::integer,(item->>'x')::numeric,(item->>'y')::numeric,coalesce((item->>'zoom')::numeric,1),coalesce(t,'{"enabled":false,"photoCutInches":2.5,"cutInches":3.25}'::jsonb));
   n=n+1;
  end if;
 end loop;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_print_crop_save(p_hash text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; j public.gallery_print_jobs; item jsonb; seen uuid[]='{}'; n integer=0;
begin
 s=public.gallery_station_check(p_hash,'print');
 perform 1 from public.gallery_events where id=s.event_id for update;
 if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 200 then raise exception 'Invalid selection';end if;
 for item in select value from jsonb_array_elements(p_items) order by value->>'id' loop
  if jsonb_typeof(item)<>'object' or not(item ?& array['id','version','x','y','zoom']) or (item-array['id','version','x','y','zoom'])<>'{}'::jsonb then raise exception 'Invalid adjustment';end if;
  select * into j from public.gallery_print_jobs where id=(item->>'id')::uuid and event_id=s.event_id for update;
  if not found or j.id=any(seen) or j.status<>'pending' or j.letter_batch_id is not null or j.print_run_id is not null or j.version is distinct from (item->>'version')::integer then raise exception 'Queue changed; reload before saving' using errcode='PT409';end if;
  if jsonb_typeof(item->'x')<>'number' or jsonb_typeof(item->'y')<>'number' or jsonb_typeof(item->'zoom')<>'number'
   or (item->>'x')::numeric not between 0 and 100 or (item->>'y')::numeric not between 0 and 100 or (item->>'zoom')::numeric not between 1 and 3 then raise exception 'Invalid crop';end if;
  if not exists(select 1 from public.gallery_photos where id=j.source_photo_id and event_id=s.event_id and ready and not hidden) then raise exception 'Photo unavailable';end if;
  update public.gallery_print_jobs set print_crop=item-array['id','version'],version=version+1,updated_at=now() where id=j.id;
  insert into public.gallery_activity_log(source,actor_user_id,event_id,action,outcome,subject_reference,details)
  values('backend',s.actor_id,s.event_id,'station.crop.save','committed',j.id::text,jsonb_build_object('before',coalesce(j.print_crop,jsonb_build_object('x',j.x,'y',j.y,'zoom',j.zoom)),'after',item-array['id','version']));
  seen=array_append(seen,j.id);n=n+1;
 end loop;
 return jsonb_build_object('updated',n);
end $function$

CREATE OR REPLACE FUNCTION public.gallery_print_run(p_hash text, p_action text, p_request uuid DEFAULT NULL::uuid, p_profile text DEFAULT 'letter'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations;
begin
 s=public.gallery_station_check(p_hash,'print');
 if exists(select 1 from public.gallery_helper_runs h join public.gallery_print_runs r on r.id=h.id where r.event_id=s.event_id and h.state='active') then
  raise exception 'Resolve the automatic print run in the owner dashboard first' using errcode='PT409';
 end if;
 return public.gallery_print_run_manual(p_hash,p_action,p_request,p_profile);
end $function$

CREATE OR REPLACE FUNCTION public.gallery_print_run_manual(p_hash text, p_action text, p_request uuid DEFAULT NULL::uuid, p_profile text DEFAULT 'letter'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; r public.gallery_print_runs; j public.gallery_print_jobs; ids uuid[]='{}'; total integer=0; t jsonb; fallback jsonb; cut numeric;
begin
 s=public.gallery_station_check(p_hash,'print');
 perform 1 from public.gallery_events where id=s.event_id for update;
 if p_action is null or p_action not in ('status','claim','printed','release','authorize') then raise exception 'Invalid action';end if;
 if p_action='status' then
  select * into r from public.gallery_print_runs where event_id=s.event_id and status='active';
 else
  if p_request is null then raise exception 'Request required';end if;
  select * into r from public.gallery_print_runs where id=p_request and event_id=s.event_id for update;
 end if;
 if p_action='claim' and r.id is null then
  select * into r from public.gallery_print_runs where event_id=s.event_id and status='active' for update;
  if r.id is null then
   if p_profile is null or p_profile not in ('letter','8x12','4x6') then raise exception 'Invalid paper';end if;
   if exists(select 1 from public.gallery_print_jobs where event_id=s.event_id and status='printing') then raise exception 'Finish the reserved photos first' using errcode='PT409';end if;
   select template into fallback from public.gallery_magnet_templates where event_id=s.event_id;
   fallback=coalesce(fallback,'{"enabled":false,"photoCutInches":2.5,"cutInches":3.25}'::jsonb);
   for j in select job.* from public.gallery_print_jobs job join public.gallery_photos p on p.id=job.source_photo_id and p.event_id=job.event_id
    where job.event_id=s.event_id and job.status='pending' and job.letter_batch_id is null and job.print_run_id is null and p.ready and not p.hidden
    order by job.created_at,job.id limit 200 for update of job loop
    if total+j.quantity>200 then exit;end if;
    t=coalesce(j.template,fallback);
    cut=case when coalesce((t->>'enabled')::boolean,false) then (t->>'cutInches')::numeric else (t->>'photoCutInches')::numeric end;
    if cut is null or cut<2.5 or cut>(case when p_profile='8x12' then 3.75 else 3.6 end) then raise exception 'Cut size does not fit the selected paper' using errcode='PT422';end if;
    ids=array_append(ids,j.id);total=total+j.quantity;
   end loop;
   if total=0 then return jsonb_build_object('run',null,'empty',true);end if;
   insert into public.gallery_print_runs(id,event_id,profile,job_ids) values(p_request,s.event_id,p_profile,ids) returning * into r;
   update public.gallery_print_jobs set status='printing',print_run_id=r.id,sheet_profile=p_profile,template=coalesce(template,fallback),version=version+1,updated_at=now() where id=any(ids) and event_id=s.event_id;
  end if;
 elsif p_action in ('printed','release','authorize') then
  if r.id is null then raise exception 'Print run unavailable' using errcode='PT409';end if;
  if r.status='active' then
   if p_action='authorize' then
    if (select count(*) from public.gallery_print_jobs q join public.gallery_photos p on p.id=q.source_photo_id and p.event_id=q.event_id
       where q.print_run_id=r.id and q.event_id=s.event_id and q.status='printing' and p.ready and not p.hidden)<>cardinality(r.job_ids) then
     raise exception 'Reserved photos changed or are unavailable' using errcode='PT409';
    end if;
    -- Recheck existing paid-order triggers immediately before each print attempt.
    update public.gallery_print_jobs set print_run_id=null where print_run_id=r.id and event_id=s.event_id;
    update public.gallery_print_jobs set print_run_id=r.id where id=any(r.job_ids) and event_id=s.event_id and status='printing';
   else
    update public.gallery_print_jobs set status=case when p_action='printed' then 'printed' else 'pending' end,print_run_id=null,version=version+1,updated_at=now() where print_run_id=r.id and event_id=s.event_id;
    update public.gallery_print_runs set status=case when p_action='printed' then 'printed' else 'released' end,finished_at=now() where id=r.id returning * into r;
   end if;
  elsif p_action='authorize' then raise exception 'Print run already finished' using errcode='PT409';end if;
 end if;
 if r.id is null then return jsonb_build_object('run',null);end if;
 if p_action<>'status' then
  insert into public.gallery_activity_log(source,actor_user_id,event_id,action,outcome,subject_reference,details) values('backend',s.actor_id,s.event_id,'station.run.'||p_action,'committed',r.id::text,jsonb_build_object('photos',cardinality(r.job_ids)));
 end if;
 return jsonb_build_object('run',to_jsonb(r)||jsonb_build_object('jobs',coalesce((select jsonb_agg(to_jsonb(q) order by array_position(r.job_ids,q.id)) from public.gallery_print_jobs q where q.id=any(r.job_ids) and q.event_id=s.event_id),'[]'::jsonb)));
end $function$

CREATE OR REPLACE FUNCTION public.gallery_print_update(p_hash text, p_id uuid, p_version integer, p_action text, p_quantity integer DEFAULT 1, p_x numeric DEFAULT 50, p_y numeric DEFAULT 50, p_zoom numeric DEFAULT 1, p_template jsonb DEFAULT NULL::jsonb)
 RETURNS gallery_print_jobs
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; j public.gallery_print_jobs;
begin
 s=public.gallery_station_check(p_hash,'print');
 select * into j from public.gallery_print_jobs where id=p_id and event_id=s.event_id for update;
 if not found or j.version<>p_version then raise exception 'Queue changed; refresh first' using errcode='PT409'; end if;
 if j.letter_batch_id is not null then raise exception 'Use the letter batch controls for this photo' using errcode='PT409'; end if;
 if p_action='claim' and j.status='pending' then
  j.status='printing'; if j.source_request_id is not null or j.source_order_upload_id is not null then
   if p_quantity<>j.quantity then raise exception 'Purchased copies cannot change';end if;
   j.print_crop=jsonb_build_object('x',p_x,'y',p_y,'zoom',p_zoom);
  else j.quantity=p_quantity; j.x=p_x; j.y=p_y; j.zoom=p_zoom;j.print_crop=null;end if; j.template=p_template;
 elsif p_action='printed' and j.status='printing' then j.status='printed';
 elsif p_action='retry' and j.status in ('printing','held') then j.status='pending';
 elsif p_action='hold' and j.status='pending' then j.status='held';
 else raise exception 'Invalid print transition' using errcode='PT409'; end if;
 update public.gallery_print_jobs set status=j.status,quantity=j.quantity,x=j.x,y=j.y,zoom=j.zoom,template=j.template,print_crop=j.print_crop,version=version+1,updated_at=now() where id=j.id returning * into j;
 insert into public.gallery_activity_log(source,actor_user_id,event_id,action,outcome,subject_reference,details)
 values('backend',s.actor_id,s.event_id,'station.print.'||p_action,'committed',j.id::text,jsonb_build_object('quantity',j.quantity,'version',j.version));
 return j;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_production_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='INSERT' and new.source_photo_id is null then new.source_photo_id=new.id; end if;
 if not exists(select 1 from public.gallery_photos where id=new.source_photo_id and event_id=new.event_id) then raise exception 'Wrong event photo'; end if;
 if new.source_request_id is not null and (tg_op='INSERT' or new.status='printing') then
  if not exists(select 1 from public.gallery_requests r where r.id=new.source_request_id and r.event_id=new.event_id and r.status in ('submitted','preparing','ready')) then raise exception 'Order unavailable'; end if;
  if (select count(*) from public.gallery_payments gp cross join lateral jsonb_array_elements(gp.lines) l where l->>'request_id'=new.source_request_id::text)<>1 or not exists(
   select 1 from public.gallery_payments gp cross join lateral jsonb_array_elements(gp.lines) l where l->>'request_id'=new.source_request_id::text and l->>'match_status'='matched' and gp.financial_status='paid' and not gp.cancelled and not gp.refund_activity and not gp.is_test
  ) then raise exception 'Verified payment required' using errcode='PT409'; end if;
  if tg_op='UPDATE' and (new.quantity,new.x,new.y,new.zoom) is distinct from (old.quantity,old.x,old.y,old.zoom) then raise exception 'Paid order crop and quantity are fixed'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_purge_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare locked_at timestamptz;
begin
 if tg_table_name='gallery_events' then
  if old.purge_started_at is not null and (new.active or new.deleted_at is null or new.purge_started_at is distinct from old.purge_started_at or new.name is distinct from old.name) then raise exception 'Permanent deletion in progress'; end if;
 else
  select purge_started_at into locked_at from gallery_events where id=new.event_id for share;
  if locked_at is not null then raise exception 'Permanent deletion in progress'; end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.gallery_sheet_claim(p_hash text, p_request uuid, p_template jsonb, p_partial boolean, p_profile text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations; batch uuid; ids uuid[]; n integer; j public.gallery_print_jobs; t jsonb; cut numeric;
begin
 if p_profile not in ('letter','8x12') or p_profile is null then raise exception 'Invalid paper profile'; end if;
 s=public.gallery_station_check(p_hash,'print');
 perform 1 from public.gallery_events where id=s.event_id for update;
 if p_request is null or p_partial is null then raise exception 'Invalid batch request' using errcode='PT422'; end if;
 select letter_batch_id into batch from public.gallery_print_jobs where event_id=s.event_id and letter_batch_id=p_request limit 1;
 if batch is null then select letter_batch_id into batch from public.gallery_print_jobs where event_id=s.event_id and status='printing' and letter_batch_id is not null limit 1; end if;
 if batch is not null then return jsonb_build_object('created',false,'id',batch,'jobs',(select jsonb_agg(to_jsonb(q) order by q.letter_slot) from public.gallery_print_jobs q where q.event_id=s.event_id and q.letter_batch_id=batch)); end if;
 select array_agg(q.id order by q.created_at,q.id) into ids from (
  select job.id,job.created_at from public.gallery_print_jobs job join public.gallery_photos p on p.id=job.source_photo_id and p.event_id=job.event_id
  where job.event_id=s.event_id and job.status='pending' and job.quantity=1 and job.letter_batch_id is null and p.ready and not p.hidden
  order by job.created_at,job.id limit 6 for update of job skip locked
 ) q;
 n=coalesce(array_length(ids,1),0);
 if n=0 or (n<6 and not p_partial) then return jsonb_build_object('waiting',true,'count',n); end if;
 for i in 1..n loop
  select * into j from public.gallery_print_jobs where id=ids[i];
  t=coalesce(j.template,p_template);
  cut=case when coalesce((t->>'enabled')::boolean,false) then (t->>'cutInches')::numeric else (t->>'photoCutInches')::numeric end;
  if t is null or cut is null or cut<2.5 or cut>(case when p_profile='8x12' then 3.75 else 3.6 end) then raise exception 'Cut size does not fit the selected sheet' using errcode='PT422'; end if;
  update public.gallery_print_jobs set status='printing',sheet_profile=p_profile,letter_batch_id=p_request,letter_slot=i-1,template=t,version=version+1,updated_at=now() where id=j.id;
 end loop;
 insert into public.gallery_activity_log(source,actor_user_id,event_id,action,outcome,subject_reference,details)
 values('backend',s.actor_id,s.event_id,'station.letter.claim','committed',p_request::text,jsonb_build_object('photos',n));
 return jsonb_build_object('created',true,'id',p_request,'jobs',(select jsonb_agg(to_jsonb(q) order by q.letter_slot) from public.gallery_print_jobs q where q.event_id=s.event_id and q.letter_batch_id=p_request));
end $function$

CREATE OR REPLACE FUNCTION public.gallery_station_check(p_hash text, p_purpose text)
 RETURNS gallery_stations
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.gallery_stations;
begin
 select * into s from public.gallery_stations where token_hash=p_hash and purpose=p_purpose for update;
 if not found or s.revoked or s.expires_at<=now() or not exists(select 1 from public.gallery_admins where user_id=s.actor_id) then raise exception 'Station unavailable' using errcode='PT403'; end if;
 perform 1 from public.gallery_events where id=s.event_id and deleted_at is null and purge_started_at is null for update;
 if not found then raise exception 'Event unavailable' using errcode='PT403'; end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION public.gallery_studio_open(p_user uuid, p_link text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare eid uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select event_id into eid from public.gallery_experiences where studio_user=p_user;
 if eid is null then
  insert into public.gallery_events(name,event_date) values('My photo magnets',current_date) returning id into eid;
  insert into public.gallery_experiences(event_id,token_hash,closes_at,studio_user,moderation,guest_limit,event_limit) values(eid,p_link,now()+interval '30 days',p_user,false,200,200);
 else
  if not exists(select 1 from public.gallery_events where id=eid and active and deleted_at is null and purge_started_at is null) then raise exception 'Workspace unavailable'; end if;
  update public.gallery_experiences set token_hash=p_link,closes_at=now()+interval '30 days',enabled=true where event_id=eid;
 end if;
 insert into public.gallery_access(event_id,user_id,expires_at) values(eid,p_user,now()+interval '30 days') on conflict(event_id,user_id) do update set expires_at=excluded.expires_at,revoked=false;
 return eid;
end $function$

CREATE OR REPLACE FUNCTION public.record_gallery_payment(p_delivery text, p_topic text, p_order jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 oid text:=p_order->>'order_id';
 prior public.gallery_payments%rowtype;
 l jsonb; normalized jsonb:='[]'; ref text; rid uuid; expected_count int; expected_cents int; magnet_count int; result text; snapshot_status text; sample boolean;
begin
 if oid is null or oid !~ '^[0-9]{1,25}$' or length(p_delivery)>200 or length(p_delivery)<1 or p_topic not in ('orders/paid','orders/updated','orders/cancelled','refunds/create') then raise exception 'Invalid delivery';end if;
 perform pg_advisory_xact_lock(hashtextextended(oid,0));
 if exists(select 1 from public.gallery_payment_events where delivery_id=p_delivery) then return '{"duplicate":true}';end if;
 if p_topic='refunds/create' then
  if p_order->>'refund_id' is null or (p_order->>'refund_id') !~ '^[0-9]{1,25}$' then raise exception 'Invalid refund';end if;
  insert into public.gallery_payment_refunds(refund_id,order_id) values(p_order->>'refund_id',oid) on conflict do nothing;
  update public.gallery_payments set refund_activity=true,received_at=now() where order_id=oid;
 else
  if jsonb_typeof(p_order->'lines') is distinct from 'array' or jsonb_array_length(p_order->'lines')>250 or p_order->>'updated_at' is null then raise exception 'Invalid order';end if;
  select * into prior from public.gallery_payments where order_id=oid for update;
  -- Older deliveries cannot revert a refund/cancellation or overwrite newer selections.
  if prior.order_id is not null and prior.shop_updated_at>(p_order->>'updated_at')::timestamptz then
   insert into public.gallery_payment_events(delivery_id,topic,order_id) values(p_delivery,p_topic,oid);
   return '{"stale":true}';
  end if;
  for l in select value from jsonb_array_elements(p_order->'lines') loop
   ref:=l->>'reference';rid:=null;magnet_count:=null;snapshot_status:=null;sample:=null;
   select pack.count,case when (l->>'unit_cents')::bigint in (pack.cents,pack.legacy_cents) then (l->>'unit_cents')::int else case when pack.count=3 then pack.cents else pack.cents-1 end end into expected_count,expected_cents from (values
    ('52451454320928',3,1499,null::int),('52451454353696',3,1499,null::int),
    ('52368201875744',6,2500,null::int),('52368201908512',12,3900,4500),('52368201941280',24,6900,8000),('52368201974048',48,11900,12500),
    ('52214866018592',6,2500,null::int),('52214866051360',12,3900,null::int),('52214866084128',24,6900,null::int),('52214866116896',48,11900,null::int)
   ) as pack(variant,count,cents,legacy_cents) where pack.variant=l->>'variant_id';
   result:='missing_reference';
   if ref ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    select r.id,r.status,e.is_sample,(select sum((x->>'quantity')::int) from jsonb_array_elements(r.items) x) into rid,snapshot_status,sample,magnet_count
    from public.gallery_requests r join public.gallery_events e on e.id=r.event_id where r.id=ref::uuid;
    result:=case when rid is null then 'unknown_reference' when sample then 'sample_gallery' when snapshot_status='cancelled' then 'cancelled_selection'
     when expected_count is null then 'wrong_product' when (l->>'quantity')::int<>1 or magnet_count<>expected_count or (l->>'count')::int is distinct from expected_count then 'quantity_mismatch'
     when p_order->>'currency'<>'USD' or (l->>'unit_cents')::bigint<>expected_cents then 'price_mismatch' else 'matched' end;
   end if;
   if result='matched' and (
    (select count(*) from jsonb_array_elements(p_order->'lines') x where x->>'reference'=ref)>1 or
    exists(select 1 from public.gallery_payments gp cross join lateral jsonb_array_elements(gp.lines) x where gp.order_id<>oid and x->>'request_id'=rid::text)
   ) then
    result:='duplicate_reference';
    update public.gallery_payments gp set lines=(select jsonb_agg(case when x->>'request_id'=rid::text then x||'{"match_status":"duplicate_reference"}'::jsonb else x end) from jsonb_array_elements(gp.lines) x)
    where gp.order_id<>oid and gp.lines @> jsonb_build_array(jsonb_build_object('request_id',rid));
   end if;
   normalized:=normalized||jsonb_build_array(l||jsonb_build_object('request_id',rid,'match_status',result));
  end loop;
  if jsonb_array_length(normalized)>0 or prior.order_id is not null then
   insert into public.gallery_payments(order_id,order_name,financial_status,cancelled,is_test,currency,total_cents,shop_updated_at,lines,refund_activity,customer_email)
   values(oid,left(p_order->>'name',100),p_order->>'financial_status',(p_order->>'cancelled')::boolean,(p_order->>'is_test')::boolean,p_order->>'currency',(p_order->>'total_cents')::bigint,(p_order->>'updated_at')::timestamptz,normalized,exists(select 1 from public.gallery_payment_refunds where order_id=oid),nullif(left(p_order->>'customer_email',254),''))
   on conflict(order_id) do update set order_name=excluded.order_name,customer_email=coalesce(excluded.customer_email,gallery_payments.customer_email),
    financial_status=case when gallery_payments.shop_updated_at=excluded.shop_updated_at and gallery_payments.financial_status in ('refunded','partially_refunded','voided') then gallery_payments.financial_status else excluded.financial_status end,
    refund_activity=gallery_payments.refund_activity or excluded.refund_activity,cancelled=gallery_payments.cancelled or excluded.cancelled,is_test=excluded.is_test,currency=excluded.currency,total_cents=excluded.total_cents,
    shop_updated_at=excluded.shop_updated_at,received_at=now(),lines=excluded.lines;
  end if;
 end if;
 insert into public.gallery_payment_events(delivery_id,topic,order_id) values(p_delivery,p_topic,oid);
 return '{"recorded":true}';
end $function$

CREATE OR REPLACE FUNCTION public.snapshot_gallery_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare saved public.gallery_selections; item jsonb; checked_at timestamptz; hourly bigint; daily bigint;
begin
 if tg_op='UPDATE' then
  if (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') then raise exception 'Request snapshots are immutable';end if;
  return new;
 end if;
 if new.user_id is distinct from auth.uid() then raise exception 'Invalid requester';end if;
 if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
  raise exception 'Request creation requires read committed isolation';
 end if;
 select * into saved from public.gallery_selections where event_id=new.event_id and user_id=auth.uid() for update;
 if not found or saved.revision<>new.selection_revision or jsonb_array_length(saved.items)=0 then raise exception 'Save a nonempty current selection first';end if;
 -- Preserve the API's existing duplicate/retry reconciliation, even at the limit.
 if exists(select 1 from public.gallery_requests r where r.event_id=new.event_id and r.user_id=new.user_id and r.selection_revision=new.selection_revision) then
  raise unique_violation using message='Request already exists',constraint='gallery_requests_event_id_user_id_selection_revision_key';
 end if;
 checked_at=clock_timestamp();
 select count(*) filter(where r.created_at>checked_at-interval '1 hour'),count(*)
 into hourly,daily from public.gallery_requests r
 where r.user_id=new.user_id and r.event_id=new.event_id and r.created_at>checked_at-interval '24 hours';
 if hourly>=20 or daily>=100 then
  raise sqlstate 'PT429' using message='Too many new order requests. Your photos are saved. Please wait before starting another order.';
 end if;
 for item in select value from jsonb_array_elements(saved.items) loop
  if not exists(select 1 from public.gallery_photos p where p.id=(item->>'photoId')::uuid and p.event_id=new.event_id and p.ready and not p.hidden) then raise exception 'A selected photo is unavailable';end if;
 end loop;
 new.items=saved.items;new.status='submitted';new.created_at=checked_at;new.email=coalesce(auth.jwt()->>'email','');return new;
end;$function$

CREATE OR REPLACE FUNCTION public.validate_gallery_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb;seen uuid[]='{}';photo uuid;
begin
 if new.items is null or jsonb_typeof(new.items) is distinct from 'array' then raise exception 'Invalid selection'; end if;
 if octet_length(new.items::text)>32768 then raise exception 'Selection exceeds the allowed size'; end if;
 if jsonb_typeof(new.items)<>'array' or jsonb_array_length(new.items)>50 then raise exception 'Invalid selection'; end if;
 if tg_op='UPDATE' and (new.event_id<>old.event_id or new.user_id<>old.user_id or new.revision<>old.revision+1) then raise exception 'Invalid revision'; end if;
 if tg_op='INSERT' and new.revision<>1 then raise exception 'Invalid revision'; end if;
 for item in select value from jsonb_array_elements(new.items) loop
  if jsonb_typeof(item)<>'object' or not(item ?& array['photoId','quantity','x','y']) then raise exception 'Invalid photo';end if;
  if (item-array['photoId','quantity','x','y','zoom'])<>'{}'::jsonb then raise exception 'Unexpected selection fields';end if;
  if jsonb_typeof(item->'photoId') is distinct from 'string' then raise exception 'Invalid photo';end if;
  if item ? 'zoom' then
   if jsonb_typeof(item->'zoom') is distinct from 'number' then raise exception 'Invalid zoom';end if;
   if (item->>'zoom')::numeric not between 1 and 3 then raise exception 'Invalid zoom';end if;
  end if;
  photo=(item->>'photoId')::uuid;
  if photo=any(seen) or not exists(select 1 from public.gallery_photos p where p.id=photo and p.event_id=new.event_id and not p.hidden) then raise exception 'Unavailable photo'; end if;
  if jsonb_typeof(item->'quantity')<>'number' or (item->>'quantity')::numeric not between 1 and 12 or trunc((item->>'quantity')::numeric)<>(item->>'quantity')::numeric then raise exception 'Invalid quantity';end if;
  if jsonb_typeof(item->'x')<>'number' or jsonb_typeof(item->'y')<>'number' or (item->>'x')::numeric not between 0 and 100 or (item->>'y')::numeric not between 0 and 100 then raise exception 'Invalid crop';end if;
  seen=array_append(seen,photo);
 end loop;
 new.updated_at=now();return new;
end;$function$
